// ── 3. Admin user ──

// Пароль — из ADMIN_PASSWORD в окружении или .env.local (сид идёт из tsx, Next
// его env-файлы сюда не подгружает). Сборка пересеивает БД, поэтому пароль,
// сменённый в админке, жил бы до первого деплоя; env переживает деплой.
// Без пароля seed останавливается до удаления данных.
function readAdminPassword(): string {
  if (process.env.ADMIN_PASSWORD) return process.env.ADMIN_PASSWORD;
  try {
    const env = readFileSync(".env.local", "utf8");
    const m = env.match(/^ADMIN_PASSWORD=(.+)$/m);
    if (m) return m[1].trim().replace(/^["']|["']$/g, "");
  } catch {
    /* файла нет — дев-окружение */
  }
  throw new Error("ADMIN_PASSWORD is required before seeding the database");
}

const passwordHash = bcrypt.hashSync(initialAdminPassword, 10);
db.insert(adminUsers)
  .values({ username: "admin", passwordHash, createdAt: new Date().toISOString() })
  .run();
